#!/usr/bin/env bash
python3 -c $'import sys,json\ns=sys.argv[1] if len(sys.argv)>1 else "1011"\nR=json.loads(sys.argv[2]) if len(sys.argv)>2 else {"0,0":[0,"0",1],"0,1":[0,"1",1],"0,_":[1,"_",-1],"1,1":[1,"0",-1],"1,0":[2,"1",0],"1,_":[2,"1",0]}\nassert all(len(v)==3 and v[2] in (-1,0,1) and isinstance(v[0],int) and isinstance(v[1],str) and len(v[1])==1 for v in R.values())\nq=h=0;t={i:c for i,c in enumerate(s) if c!="_"};hist=[]\nwhile True:\n hist.append([q,h,sorted(t.items())]);v=R.get(str(q)+","+t.get(h,"_"))\n if v is None:break\n q,w,d=v\n if w=="_":t.pop(h,None)\n else:t[h]=w\n h+=d\nb=json.dumps([R,s,hist],sort_keys=True,separators=(",",":")).encode()\ndef primes(n):\n a=[];k=2\n while len(a)<n:\n  if all(k%p for p in a if p*p<=k):a.append(k)\n  k+=1\n return a\nP=primes(len(b));g=1\nfor p,v in zip(P,b):g*=pow(p,v+1)\nu=g;out=[]\nfor p in P:\n e=0\n while u%p==0:u//=p;e+=1\n assert 1<=e<=256\n out.append(e-1)\nassert u==1 and bytes(out)==b\nprint(json.dumps(dict(steps=len(hist)-1,halted=True,godel_bits=g.bit_length(),roundtrip=True,conditional_entropy_bits=0,final=hist[-1]),ensure_ascii=False))' "$@"
